VALUES (5634, 'Métricas Urbanas - Abordagens paramétricas para planejamento de bairros e cidades mais sustentáveis', 'metricas-urbanas-abordagens-parametricas-para-planejamento-de-bairros-e-cidades-mais-sustentaveis', 'Este livro apresenta um sistema e um conjunto de ferramentas obtidos como resultados de um projeto de pesquisa que abordou um tema relevante e emergente na área de Arquitetura e Urbanismo, ainda não consolidado no contexto da pós-graduação brasileira: a aplicação de recursos algorítmicos e de linguagens de programação visual no processo de projeto urbano, com o objetivo de propor bairros e cidades sustentáveis.\r\n\r\n<span class="im"><strong>Editora</strong>: [acf field="editora"]</span>\r\n\r\n<strong>Midia</strong>: [acf field="midia"]\r\n\r\n<strong>Tema</strong>: [acf field="tema"]\r\n\r\n<strong>Autores</strong>: [acf field="autores"]\r\n\r\n<strong>Idioma</strong>: [acf field="idioma"]\r\n\r\n<strong>Local de publicação</strong>: [acf field="publicacao"]\r\n\r\n<strong>País</strong>: [acf field="pais"]\r\n\r\n<strong>Ano de publicação</strong>: [acf field="ano"]\r\n\r\n<strong>Acervo</strong>: [acf field="tipo_de_acervo"]', 0, (SELECT id FROM product_categories WHERE wp_id = 201 LIMIT 1), 'published', '2020-03-18 15:27:03') 
ON CONFLICT (slug) DO NOTHING;
VALUES (5637, 'Vectorworks passo a passo caderno de exercícios', 'vectorworks-passo-a-passo-caderno-de-exercicios', 'Vectorworks passo a passo – caderno de exercícios é o material ideal para quem quer aproveitar o máximo das atividades propostas que cobrem grande parte dos assuntos explicados no livro Vectorworks passo a passo.\r\n\r\n<span class="im"><strong>Editora</strong>: [acf field="editora"]</span>\r\n\r\n<strong>Midia</strong>: [acf field="midia"]\r\n\r\n<strong>Tema</strong>: [acf field="tema"]\r\n\r\n<strong>Autores</strong>: [acf field="autores"]\r\n\r\n<strong>Idioma</strong>: [acf field="idioma"]\r\n\r\n<strong>Local de publicação</strong>: [acf field="publicacao"]\r\n\r\n<strong>País</strong>: [acf field="pais"]\r\n\r\n<strong>Ano de publicação</strong>: [acf field="ano"]\r\n\r\n<strong>Acervo</strong>: [acf field="tipo_de_acervo"]', 0, (SELECT id FROM product_categories WHERE wp_id = 195 LIMIT 1), 'published', '2020-03-18 18:30:57') 
