VALUES (7172, 'Gerenciamento e Coordenação de Projetos BIM', 'gerenciamento-e-coordenacao-de-projetos-bim', 'Building Information Modeling (BIM): sua eficiência no gerenciamento e na coordenação. Sérgio Roberto Leusin apresenta indicadores e ferramentas usadas no gerenciamento dos projetos, além de abordar as características dos softwares mais comuns do mercado.\r\n\r\nCom destaque para a área imobiliária e grandes organizações proprietárias, Gerenciamento e Coordenação de Projetos BIM traz as boas práticas no gerenciamento e coordenação de projetos, inclusive com exemplos de procedimentos de contratação e controle de projeto. O autor ainda faz a análise de funcionalidades para efeito de seleção da solução.\r\n\r\n<span class="im"><strong>Editora</strong>: [acf field="editora"]</span>\r\n\r\n<strong>Midia</strong>: [acf field="midia"]\r\n\r\n<strong>Tema</strong>: [acf field="tema"]\r\n\r\n<strong>Autores</strong>: [acf field="autores"]\r\n\r\n<strong>Idioma</strong>: [acf field="idioma"]\r\n\r\n<strong>Local de publicação</strong>: [acf field="publicacao"]\r\n\r\n<strong>País</strong>: [acf field="pais"]\r\n\r\n<strong>Ano de publicação</strong>: [acf field="ano"]\r\n\r\n<strong>Acervo</strong>: [acf field="tipo_de_acervo"]', 0, (SELECT id FROM product_categories WHERE wp_id = 199 LIMIT 1), 'published', '2020-09-21 15:52:38') 
ON CONFLICT (slug) DO NOTHING;
VALUES (7173, 'CAD Criativo', 'cad-criativo', 'Será possível unir lógica matemática e programação de computadores ao design criativo? Cad Criativo mostra que através da automatização é possível explorar um número maior de alternativas e conseqüentemente chegar a uma solução mais interessante.\r\n\r\n<span class="im"><strong>Editora</strong>: [acf field="editora"]</span>\r\n\r\n<strong>Midia</strong>: [acf field="midia"]\r\n\r\n<strong>Tema</strong>: [acf field="tema"]\r\n\r\n<strong>Autores</strong>: [acf field="autores"]\r\n\r\n<strong>Idioma</strong>: [acf field="idioma"]\r\n\r\n<strong>Local de publicação</strong>: [acf field="publicacao"]\r\n\r\n<strong>País</strong>: [acf field="pais"]\r\n\r\n<strong>Ano de publicação</strong>: [acf field="ano"]\r\n\r\n<strong>Acervo</strong>: [acf field="tipo_de_acervo"]', 0, (SELECT id FROM product_categories WHERE wp_id = 206 LIMIT 1), 'published', '2020-09-21 15:52:38') 
