VALUES (7651, 'Informática Novas Aplicações Com Microcomputadores', 'informatica-novas-aplicacoes-com-microcomputadores', 'Este texto fornece uma introdução à informática, percorrendo seus conceitos básicos e explorando uma estratégia para selecionar, utilizar e implementar recursos de informática, em especial de microcomputadores, mostrando suas aplicações e seus crescentes potenciais. O texto foi projetado para executivos, administradores, engenheiros, profissionais liberais e estudantes que necessitam conhecer o potencial da informática.\r\n\r\n<span class="im"><strong>Editora</strong>: [acf field="editora"]</span>\r\n\r\n<strong>Midia</strong>: [acf field="midia"]\r\n\r\n<strong>Tema</strong>: [acf field="tema"]\r\n\r\n<strong>Autores</strong>: [acf field="autores"]\r\n\r\n<strong>Idioma</strong>: [acf field="idioma"]\r\n\r\n<strong>Local de publicação</strong>: [acf field="publicacao"]\r\n\r\n<strong>País</strong>: [acf field="pais"]\r\n\r\n<strong>Ano de publicação</strong>: [acf field="ano"]\r\n\r\n<strong>Acervo</strong>: [acf field="tipo_de_acervo"]', 0, (SELECT id FROM product_categories WHERE wp_id = 181 LIMIT 1), 'published', '2022-06-15 11:32:41') 
ON CONFLICT (slug) DO NOTHING;
VALUES (7652, 'Arquitetura De Software - Desenvolvimento orientado para arquitetura', 'arquitetura-de-software-desenvolvimento-orientado-para-arquitetura', 'Um estudo da organização global dos sistemas de software bem como do relacionamento entre seus subsistemas e componentes, apresentando os modelos emergentes de arquitetura de software e as práticas atuais. O livro aborda os seguintes tópicos - Arquitetura de software; Estilos arquiteturais ; Requisitos arquiteturais ; Análise arquitetural ; Projeto arquitetural; Arquiteturas de domínio específico ; Arquiteturas de interface com o usuário ; Avaliação arquitetural de um sistema de informações ; Avaliação arquitetural de um sistema de telecomunicações.\r\n\r\n<span class="im"><strong>Editora</strong>: [acf field="editora"]</span>\r\n\r\n<strong>Midia</strong>: [acf field="midia"]\r\n\r\n<strong>Tema</strong>: [acf field="tema"]\r\n\r\n<strong>Autores</strong>: [acf field="autores"]\r\n\r\n<strong>Idioma</strong>: [acf field="idioma"]\r\n\r\n<strong>Local de publicação</strong>: [acf field="publicacao"]\r\n\r\n<strong>País</strong>: [acf field="pais"]\r\n\r\n<strong>Ano de publicação</strong>: [acf field="ano"]\r\n\r\n<strong>Acervo</strong>: [acf field="tipo_de_acervo"]', 0, (SELECT id FROM product_categories WHERE wp_id = 469 LIMIT 1), 'published', '2022-06-15 11:32:41') 
