VALUES (7686, 'BIM e Inovação em gestão de projetos', 'bim-e-inovacao-em-gestao-de-projetos', 'Da teoria à prática na administração de processos de projeto. BIM e Inovação em Gestão de Projetos aborda conceitos de gestão de processos de projeto, inovação, planejamento, modelagem da informação, qualidade dos modelos, competência e maturidade em BIM.\r\n\r\n<span class="im"><strong>Editora</strong>: [acf field="editora"]</span>\r\n\r\n<strong>Midia</strong>: [acf field="midia"]\r\n\r\n<strong>Tema</strong>: [acf field="tema"]\r\n\r\n<strong>Autores</strong>: [acf field="autores"]\r\n\r\n<strong>Idioma</strong>: [acf field="idioma"]\r\n\r\n<strong>Local de publicação</strong>: [acf field="publicacao"]\r\n\r\n<strong>País</strong>: [acf field="pais"]\r\n\r\n<strong>Ano de publicação</strong>: [acf field="ano"]\r\n\r\n<strong>Acervo</strong>: [acf field="tipo_de_acervo"]', 0, (SELECT id FROM product_categories WHERE wp_id = 477 LIMIT 1), 'published', '2022-06-15 11:32:59') 
